/* From Uiverse.io by arshshaikh06 - Tags: card, fluid, animated, colorful, palette, card hover */
.__UIV_SCOPE__ .container {
  width: 300px;
  height: 340px;
  border-radius: 1em;
  overflow: hidden;
  box-shadow: 0 10px 20px #dbdbdb;
  font-family: sans-serif;
  background: white;
  pointer-events: none;
}

.__UIV_SCOPE__ .palette {
  position: relative;
  width: 300px;
  height: 300px;
  border-radius: 1rem;
  overflow: hidden;
  pointer-events: auto;
}

.__UIV_SCOPE__ .palette:hover > #color-code {
  opacity: 0;
}

.__UIV_SCOPE__ .color {
  position: absolute;
  width: 300px;
  height: 300px;
  transform-origin: center;
  transition: 0.3s ease-in-out;
  box-sizing: inline-block;
  display: flex;
  align-items: center;
  justify-content: center;
}

.__UIV_SCOPE__ .color span {
  color: white;
  font-weight: 600;
  letter-spacing: 1px;
}

.__UIV_SCOPE__ #color1 {
  background: #CECE5A;
  rotate: 45deg;
  translate: 212.13px 0;
  outline: 0 solid #CECE5A;
  z-index: 9;
}

.__UIV_SCOPE__ #color1:hover {
  translate: 0 0;
  rotate: 0deg;
  z-index: 99;
  outline: 20px solid #CECE5A;
}

.__UIV_SCOPE__ #color2 {
  background: #FFE17B;
  rotate: 45deg;
  translate: 0 212.13px;
  outline: 0 solid #FFE17B;
  z-index: 9;
}

.__UIV_SCOPE__ #color2:hover {
  translate: 0 0;
  rotate: 0deg;
  z-index: 99;
  outline: 20px solid #FFE17B;
}

.__UIV_SCOPE__ #color2 span {
  color: #1A1A1A;
}

.__UIV_SCOPE__ #color3 {
  background: #FD8D14;
  rotate: 45deg;
  translate: -212.13px 0;
  outline: 0 solid #FD8D14;
  z-index: 9;
}

.__UIV_SCOPE__ #color3:hover {
  translate: 0 0;
  rotate: 0deg;
  z-index: 99;
  outline: 20px solid #FD8D14;
}

.__UIV_SCOPE__ #color4 {
  background: #C51605;
  rotate: 45deg;
  translate: 0 -212.13px;
  outline: 0 solid #C51605;
  z-index: 9;
}

.__UIV_SCOPE__ #color4:hover {
  translate: 0 0;
  rotate: 0deg;
  z-index: 99;
  outline: 20px solid #C51605;
}

.__UIV_SCOPE__ #color-code {
  position: absolute;
  top: 0;
  left: 0;
  width: 40px;
  height: 40px;
  translate: 130px 130px;
  border-radius: 20px;
  overflow: hidden;
  z-index: 199;
  opacity: 1;
  transition: 0.3s ease-in-out;
}

.__UIV_SCOPE__ #color-code-bg {
  position: absolute;
  width: 40px;
  height: 40px;
  background-color: rgba(255, 255, 255, 0.8);
  filter: blur(10px);
}

.__UIV_SCOPE__ #color-code-text {
  position: absolute;
  width: 40px;
  height: 40px;
  display: flex;
  justify-content: center;
  align-items: center;
}

.__UIV_SCOPE__ #color-code-text::after {
  content: "v2";
  font-weight: 600;
  font-family: sans-serif;
  color: #1a1a1a;
}

.__UIV_SCOPE__ #footer {
  height: 12%;
  width: 100%;
  background: white;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 1em;
  box-sizing: border-box;
  color: #bebebe;
}

.__UIV_SCOPE__ #footer svg {
  scale: 0.75;
}

.__UIV_SCOPE__ #footer #bookmarks {
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: smaller;
}
